import{d as e,i as t}from"./index-BVdLvPw-.js";import{t as n}from"./BlogPost-BCN0DswP.js";var r=t();function i(){return(0,r.jsxs)(n,{path:`/blog-essential-eight-guide`,children:[(0,r.jsx)(`p`,{children:`The Essential Eight is a set of mitigation strategies published by the Australian Signals Directorate (ASD) to help organisations protect themselves against cyber threats. It is widely used as a practical baseline, not just by government.`}),(0,r.jsx)(`p`,{children:`It isn't a law for most private businesses, but insurers, larger customers and government buyers increasingly ask about it. Even if nobody asks, it is one of the clearest checklists available for deciding where to spend your security effort first.`}),(0,r.jsx)(`h2`,{children:`The eight strategies`}),(0,r.jsx)(`p`,{children:`The strategies fall into three broad goals: stop malicious code running, limit the damage if something gets in, and make sure you can recover.`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Application control:`}),` only approved software can run. If a staff member downloads an unknown program or opens a malicious file, it is blocked instead of executing.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Patch applications:`}),` keep apps like browsers, Office, PDF readers and anything exposed to the internet up to date. Attackers move quickly once a weakness becomes public.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Configure Microsoft Office macro settings:`}),` block risky macros. Macros from the internet should be blocked, and only trusted, approved macros allowed to run.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`User application hardening:`}),` turn off features attackers abuse, such as old browser plug-ins and unneeded scripting tools on everyday computers.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Restrict administrative privileges:`}),` fewer people with admin access, and admin accounts used only for admin tasks, never for email or web browsing.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Patch operating systems:`}),` keep Windows, macOS and servers current, and replace systems that no longer receive security updates.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Multi-factor authentication:`}),` a second check when signing in, such as an authenticator app prompt. It matters most for email, remote access and anything holding sensitive data.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Regular backups:`}),` backups you have actually tested restoring, kept somewhere ransomware on your network cannot reach or delete.`]})]}),(0,r.jsx)(`h2`,{children:`Maturity levels`}),(0,r.jsx)(`p`,{children:`Each strategy can be implemented at increasing maturity levels. The current Essential Eight Maturity Model describes Maturity Level Zero through to Maturity Level Three. Level Zero means there are weaknesses in that area. Level One is aimed at opportunistic attackers using widely available tools, while Levels Two and Three address more capable and targeted adversaries.`}),(0,r.jsx)(`p`,{children:`ASD's advice is to reach the same level across all eight strategies before moving any one of them higher. A business with excellent backups but no multi-factor authentication still has an obvious gap.`}),(0,r.jsx)(`p`,{children:`Most small businesses should aim to reach the first level across all eight, then improve from there based on risk. If you handle health records, financial data or work in a supply chain for government or critical infrastructure, Level Two may be a more realistic target.`}),(0,r.jsxs)(`p`,{children:[`ASD reviews the model from time to time and has been consulting on how its guidance will evolve. Check `,(0,r.jsx)(`b`,{children:`cyber.gov.au`}),` for the current version before you plan an assessment.`]}),(0,r.jsx)(`h2`,{children:`Where to start`}),(0,r.jsx)(`p`,{children:`You do not have to tackle all eight at once. These four steps give most small businesses the biggest improvement for the effort involved:`}),(0,r.jsxs)(`ol`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Turn on multi-factor authentication for every account.`}),` Start with email and Microsoft 365, then remote access, banking, accounting software and social media logins. If you use `,(0,r.jsx)(e,{to:`/microsoft`,children:`Microsoft 365`}),`, much of this can be enforced centrally.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Make sure backups run daily and test a restore.`}),` Restore a file, a mailbox and a whole computer or server, and note how long it took.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Remove admin rights from everyday user accounts.`}),` Give the few people who need admin access a separate admin account and use it only when required.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Automate Windows and app updates.`}),` Use central management so updates install without relying on staff, and check monthly for devices that have fallen behind.`]})]}),(0,r.jsxs)(`p`,{children:[`These four steps remove a large share of common risk. `,(0,r.jsx)(e,{to:`/cybersecurity`,children:`See how our cybersecurity service works`}),`.`]}),(0,r.jsx)(`h2`,{children:`A worked example`}),(0,r.jsx)(`p`,{children:`Imagine a 15-person accounting practice. Staff use Microsoft 365, a cloud practice management system and a few shared laptops. Everyone is a local administrator because it was easier when the computers were set up, and backups go to a USB drive that stays plugged into the office server.`}),(0,r.jsx)(`p`,{children:`In the first month, the practice enforces multi-factor authentication for all Microsoft 365 users and moves backups to a cloud service with separate credentials and retention, then tests a restore. In the second month, admin rights are removed and two named staff receive separate admin accounts. In the third, updates are managed centrally and macros from the internet are blocked. Application control and hardening come next, once the basics are stable.`}),(0,r.jsx)(`p`,{children:`None of this requires new hardware. It is mostly configuration, documentation and changing a few habits.`}),(0,r.jsx)(`h2`,{children:`Common mistakes`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Treating it as a one-off project.`}),` Patching, access reviews and backup tests need to happen on a schedule, or the controls drift.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Leaving exceptions in place.`}),` One shared mailbox or old account without multi-factor authentication is often the way in.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Backups on the same network.`}),` Ransomware commonly encrypts or deletes any backup it can reach.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Assuming the cloud handles it.`}),` Microsoft and other providers secure their platforms, but your settings, accounts and data are still your responsibility.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`No written record.`}),` Without documentation you cannot show an insurer or customer what you have done.`]})]}),(0,r.jsx)(`h2`,{children:`Quick checklist`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Multi-factor authentication on every user and admin account`}),(0,r.jsx)(`li`,{children:`Daily backups, stored separately, with a restore tested this quarter`}),(0,r.jsx)(`li`,{children:`No everyday accounts with admin rights`}),(0,r.jsx)(`li`,{children:`Operating systems and applications updated automatically`}),(0,r.jsx)(`li`,{children:`Macros from the internet blocked`}),(0,r.jsx)(`li`,{children:`Unsupported software and devices identified and scheduled for replacement`})]}),(0,r.jsxs)(`p`,{children:[`If you also want to understand your obligations when something does go wrong, read our guide to `,(0,r.jsx)(e,{to:`/blog-notifiable-data-breaches`,children:`the Notifiable Data Breaches scheme`}),`.`]}),(0,r.jsx)(`h2`,{children:`Frequently asked questions`}),(0,r.jsx)(`h3`,{children:`Is the Essential Eight mandatory for my business?`}),(0,r.jsx)(`p`,{children:`For most private businesses it is not a legal requirement. It is mandatory for many Australian Government entities, and some contracts, tenders and cyber insurance policies may ask you to meet a particular maturity level. Check the specific contract or policy wording.`}),(0,r.jsx)(`h3`,{children:`How long does it take to reach Maturity Level One?`}),(0,r.jsx)(`p`,{children:`It depends on the number of devices, how your systems are set up today and how much legacy software you rely on. A small business with modern Microsoft 365 and current devices can often make fast progress on the four starting steps, while application control usually takes more planning.`}),(0,r.jsx)(`h3`,{children:`Does Microsoft 365 Business Premium cover the Essential Eight?`}),(0,r.jsxs)(`p`,{children:[`It includes tools that help with several strategies, such as device management, multi-factor authentication policies and macro controls. The tools still need to be configured correctly, and backups and patching of other software need separate attention. Our `,(0,r.jsx)(e,{to:`/blog-microsoft-365-plans-compared`,children:`Microsoft 365 plan comparison`}),` explains what each plan includes.`]}),(0,r.jsx)(`h3`,{children:`Can we do this ourselves?`}),(0,r.jsxs)(`p`,{children:[`Many businesses can complete the first steps in-house. Where it helps to have someone document the setup, manage updates and test backups on a schedule, our `,(0,r.jsx)(e,{to:`/support-services`,children:`managed IT support`}),` team can help.`]})]})}export{i as default};